      "codigo_refatorado": "using System; using System.Text; using System.Collections.Generic; using UnityEngine; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressGc = false; public bool stressCpu = false; public bool stressDraw = false; public GameObject testPrefab; [Range(1, 20)] public float spawnRadius = 10f; [Range(1, 50)] public int cubesPerFrame = 1; public bool useUniqueMaterials = false; [Range(1, 512)] public int cpuScansPerFrame = 1; public int emptyObjects = 0; public int gcConcatIterations = 1000; public int gcArrayAllocs = 0; public int overdrawLayers = 0; public Material overdrawMaterial; [Range(0, 2000)] public int prepopulateCount = 0; private readonly StringBuilder stringBuilderCache = new StringBuilder(2048); private static readonly List<GameObject> cachedGameObjects = new List<GameObject>(1024); private MaterialPropertyBlock propertyBlock; private static readonly int ColorPropertyId = Shader.PropertyToID(\"_Color\"); private void Awake() { propertyBlock = new MaterialPropertyBlock(); } private void Start() { if (prepopulateCount > 0 && testPrefab != null) { for (int i = 0; i < prepopulateCount; i++) { SpawnOne(); } } for (int i = 0; i < emptyObjects; i++) { new GameObject(string.Concat(\"Empty_\", i.ToString())); } if (overdrawLayers > 0 && overdrawMaterial != null) { BuildOverdrawLayers(); } } private void BuildOverdrawLayers() { Camera cam = Camera.main; if (cam == null) return; float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad; for (int i = 0; i < overdrawLayers; i++) { float d = cam.nearClipPlane + 0.05f + i * 0.001f; float h = 2f * d * Mathf.Tan(halfFov) * 1.1f; var quad = GameObject.CreatePrimitive(PrimitiveType.Quad); Destroy(quad.GetComponent<Collider>()); quad.name = string.Concat(\"Overdraw_\", i.ToString()); quad.transform.SetParent(cam.transform, false); quad.transform.localPosition = new Vector3(0f, 0f, d); quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f); quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial; } } private void Update() { if (stressGc) { stringBuilderCache.Clear(); for (int i = 0; i < gcConcatIterations; i++) { stringBuilderCache.Append(i); } string result = stringBuilderCache.ToString(); GC.KeepAlive(result); } if (stressCpu) { for (int k = 0; k < cpuScansPerFrame; k++) { UnityEngine.SceneManagement.Scene currentScene = UnityEngine.SceneManagement.SceneManager.GetActiveScene(); cachedGameObjects.Clear(); currentScene.GetRootGameObjects(cachedGameObjects); } } if (stressDraw && testPrefab != null) { int n = Mathf.Max(1, cubesPerFrame); for (int i = 0; i < n; i++) { SpawnOne(); } } } private void SpawnOne() { var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity); if (useUniqueMaterials) { var rend = clone.GetComponent<Renderer>(); if (rend != null) { rend.GetPropertyBlock(propertyBlock); propertyBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value)); rend.SetPropertyBlock(propertyBlock); } } } } }",
      "explicacao_didatica": "Em C#, strings sao imutaveis. Toda vez que fazemos string += algo dentro de um laco de repeticao, uma nova copia inteira da string e criada na memoria dinamica (heap). Quando isso acontece milhares de vezes por segundo no Update, a Unity enche a memoria rapido demais, e o Garbage Collector precisa congelar o jogo para limpar a sujeira acumulada, causando travamentos (stuttering). Substituimos isso pelo StringBuilder reaproveitado e eliminamos a criacao desnecessaria de arrays."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Uso repetitivo de GameObject.FindObjectsOfType dentro do Update() multiplicado por cpuScansPerFrame, forcando a CPU a varrer todos os objetos carregados na memoria e alocar novos arrays nativos multiplas vezes no mesmo frame.",
      "codigo_refatorado": "using System.Collections.Generic; using UnityEngine; using UnityEngine.SceneManagement; public class CpuOptimizationSample : MonoBehaviour { private static readonly List<GameObject> RootObjectsCache = new List<GameObject>(512); public void ScanSceneOptimized() { Scene activeScene = SceneManager.GetActiveScene(); RootObjectsCache.Clear(); activeScene.GetRootGameObjects(RootObjectsCache); } }",
      "explicacao_didatica": "O metodo FindObjectsOfType e um dos comandos mais pesados da Unity porque ele percorre a cena inteira buscando objeto por objeto e cria uma lista nova toda vez. Fazer isso a cada frame em um loop de CPU consome quase todo o tempo do processador (122ms). A solucao e fazer cache de referencias em listas reutilizaveis ou registrar os objetos em um Manager no momento em que sao criados."
    }
  ],
  "dicas_level_design": null
}

